#!/usr/bin/env python3
import base64,os
d="/home/admin/yuzhou-inquiry/public"
os.makedirs(d,exist_ok=True)
data={
'cat-figurines.jpg':'',
'cat-smoking.jpg':'',
'cat-candles.jpg':'',
'cat-ornaments.jpg':'',
'cat-bracelets.jpg':'',
}
for n,b in data.items():
 p=os.path.join(d,n)
 open(p,'wb').write(base64.b64decode(b))
 print('OK:',n,os.path.getsize(p),'bytes')
print('Batch3 done!')
